begin;
create table if not exists public."SeatingTable" (
    "TableNumber" integer generated by default as identity primary key,
    "Capacity" integer not null check ("Capacity" > 0)
);
-- Preserve existing guest assignments; initialize capacity to at least assigned party size.
insert into public."SeatingTable" ("TableNumber", "Capacity")
select "Table", greatest(10, sum("GuestNum"))::integer from public."Guest"
where "Table" is not null group by "Table"
on conflict ("TableNumber") do nothing;
-- Never rewind the identity sequence, even after tables are deleted.
select setval(pg_get_serial_sequence('public."SeatingTable"', 'TableNumber'),
    greatest(coalesce((select max("TableNumber") from public."SeatingTable"), 0),
        (select last_value from public."SeatingTable_TableNumber_seq"), 1),
    (select is_called from public."SeatingTable_TableNumber_seq") or exists(select 1 from public."SeatingTable"));
do $$ begin
    if not exists (select 1 from pg_constraint where conname = 'Guest_Table_fkey' and conrelid = 'public."Guest"'::regclass) then
        alter table public."Guest" add constraint "Guest_Table_fkey"
            foreign key ("Table") references public."SeatingTable" ("TableNumber") on delete restrict;
    end if;
end $$;
alter table public."SeatingTable" enable row level security;
revoke all on public."SeatingTable" from anon, authenticated;
commit;
